import{_ as i,o as t,c as a,a5 as n}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-7-create-user/report3_spec_en.md","filePath":"feature/admin-management/3-10-7-create-user/report3_spec_en.md"}'),o={name:"feature/admin-management/3-10-7-create-user/report3_spec_en.md"};function r(s,e,l,c,p,d){return t(),a("div",null,[...e[0]||(e[0]=[n("<p><strong>3.10.7 Create User (Administrative User Provisioning)</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Administrator (ADMIN) clicks &quot;+ Provision New User&quot; from the user directory (/admin/users).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Platform Administrator creating accounts directly for enterprise onboarding or technical support.</li><li><strong>Purpose</strong>: Provision ADMIN/USER accounts that must verify email and replace the initial password before normal access.</li><li><strong>Interface</strong>: Provision New User Modal (SCR-ADM-07), with profile, system role, catalog plan and mandatory activation notice.</li><li><strong>Data Processing</strong>: Validate ADMIN, unique email, profile and password policy; hash temporary password using the existing auth policy. Create PENDING_VERIFICATION with emailVerifiedAt=null, requirePasswordReset=true and zero strikes. Queue a mandatory activation email and audit creation; failed email delivery keeps the account pending.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Provision New User Modal Dialog (SCR-ADM-07):</p><ul><li>Left/Header: Modal title &quot;Provision New User Account&quot;, user-plus icon, and administrative guideline banner.</li><li>Center: Full Name, Email, temporary password/generation control, System Role ADMIN/USER and plan selector from existing subscription catalog. Activation email and initial password replacement are mandatory, with no opt-out checkboxes.</li><li>Buttons: Button &quot;Provision Account&quot; (primary button), Button &quot;Cancel&quot;.</li><li>Footer: Account starts PENDING_VERIFICATION with zero strikes. Until email verification and password replacement complete, only activation, password setup, logout and support are available.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: fullName (2–100 chars), email (valid format), role (ADMIN/USER); temporary password if not generated: minimum 8 characters, at least one digit and one special character.</li><li><strong>Input optional</strong>: phoneNumber, requestedPlanId from subscription catalog; account creation itself grants no unpaid paid-plan entitlement.</li><li><strong>System data</strong>: adminId, createdAt, initialStatus=PENDING_VERIFICATION, emailVerifiedAt=null, requirePasswordReset=true, initialStrikes=0, activation email delivery state.</li><li><strong>Output</strong>: Created user record { id, email, fullName, role, status } with HTTP 201 Created.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-01</strong>: Email is unique across the platform, using existing normalization rules.</li><li><strong>BR-02</strong>: Temporary/new passwords require at least 8 characters, one digit and one special character, with BCrypt cost 12 as specified in the source FR. Reuse the auth validation/hashing flow and reconcile any mismatch in the technical plan; never log passwords or activation tokens.</li><li><strong>BR-82</strong>: System roles are ADMIN and USER only. Agency/Workspace membership roles are managed separately. Subscription plan identifiers come from the existing catalog (currently BASIC, PRO, ENTERPRISE), not a second hardcoded catalog.</li><li><strong>BR-63</strong>: Only ADMIN provisions accounts. Mandatory activation email verifies email ownership; creation does not mark email verified.</li><li><strong>BR-15</strong>: Before both email verification and initial password replacement, allow only activation/email verification, password setup, logout and support. Block dashboard, Agency data, AI, publishing and billing operations on both UI and API.</li><li><strong>BR-15</strong>: On completion set emailVerifiedAt, clear requirePasswordReset and activate the account if no separate sanction/deletion applies. Email verification does not require Admin approval or 2FA re-enrollment.</li><li><strong>BR-60</strong>: Paid-plan entitlements follow the existing subscription/payment flow; provisioning alone is not a payment, invoice or revenue event.</li><li><strong>BR-16</strong>: Audit provisioning and activation outcomes without storing secrets.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Executing user lacks ADMIN role → Display: MSG39</li><li>Mandatory fields left blank → Display: MSG02</li><li>Email format is invalid → Display: MSG04</li><li>Password does not satisfy complexity requirements → Display: MSG05</li><li>Email already exists in database → Display: MSG08</li><li>Account provisioned successfully → Display: MSG10</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin opens SCR-ADM-07 and enters profile, ADMIN/USER role and an optional catalog plan request.</li><li>System validates uniqueness and existing auth/password rules.</li><li>Create the pending account with zero strikes and both activation requirements enforced.</li><li>Queue the mandatory activation email, record audit and show pending delivery/activation status.</li><li>User follows the activation flow, verifies email and sets a private new password.</li><li>Once both requirements pass, activate eligible account and allow normal access; paid plans still follow payment rules.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Missing ADMIN → MSG39; required fields/invalid email/password/duplicate email → existing MSG02/04/05/08.</li><li>4.a1: Email failure → retain PENDING_VERIFICATION, expose retry/resend status; do not create another account.</li><li>5.a1: Expired/used activation token → follow existing resend/verification policy; never grant application access.</li><li>6.a1: Only one prerequisite completed → retain restricted activation access; sanction/deletion cannot be bypassed.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>New account remains PENDING_VERIFICATION until mandatory activation prerequisites complete.</li><li>System role is ADMIN/USER; Agency roles and paid-plan entitlements remain separate.</li><li>Activation email delivery and audit are recorded; no password/token is logged.</li></ul>",14)])])}const g=i(o,[["render",r]]);export{m as __pageData,g as default};
